import { existsSync } from "node:fs";
import path from "node:path";

/**
 * Media for the landing page, generated by `api/scripts/landing_assets.py`
 * into web/public/landing/. Each entry resolves to a public URL when the
 * file exists and to null otherwise, so the page can fall back to its
 * SVG illustrations. Checked at request time (the route is dynamic).
 */
export type LandingMedia = {
  render: string | null;
  flats: string | null;
  tryon: string | null;
  runwayStill: string | null;
  runway: string | null;
};

const CANDIDATES: Record<keyof LandingMedia, string[]> = {
  render: ["render.jpg", "render.png"],
  flats: ["flats.jpg", "flats.png"],
  tryon: ["tryon.jpg", "tryon.png"],
  runwayStill: ["runway-still.jpg", "runway-still.png"],
  runway: ["runway.mp4"],
};

export function getLandingMedia(): LandingMedia {
  const dir = path.join(process.cwd(), "public", "landing");
  const out = {} as LandingMedia;
  for (const key of Object.keys(CANDIDATES) as (keyof LandingMedia)[]) {
    const found = CANDIDATES[key].find((name) => existsSync(path.join(dir, name)));
    out[key] = found ? `/landing/${found}` : null;
  }
  return out;
}
